Para corregir esto, debes asegurarte de que la URL en la prueba coincida con la URL en el servicio. Aquí está la prueba corregida:

```ts
import { TestBed } from "@angular/core/testing";
import { TestingService } from "./testing.service";
import {
  HttpTestingController,
  provideHttpClientTesting,
} from "@angular/common/http/testing";
import { provideHttpClient } from "@angular/common/http";

describe("TestingService", () => {
  let service: TestingService;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [provideHttpClientTesting(), provideHttpClient()],
    });
    service = TestBed.inject(TestingService);
    httpMock = TestBed.inject(HttpTestingController);
  });

  it("should be created", () => {
    expect(service).toBeTruthy();
  });

  afterEach(() => {
    httpMock.verify();
  });

  it("it should return upperCase text", () => {
    expect(service.getSimpleValue("hello")).toBe("HELLO");
  });

  it("should return users list", (done: DoneFn) => {
    const mockResponse = {
      results: Array(10).fill({ name: "John Doe" }),
    };

    service.getUsers().subscribe((value) => {
      expect(value.results.length).toBe(10);
      done();
    });

    const req = httpMock.expectOne("https://peticiones.online/api/userss");
    expect(req.request.method).toBe("GET");
    req.flush(mockResponse);
  });
});
```

En este código, he corregido la URL en `httpMock.expectOne` para que coincida con la URL definida en el servicio (`"https://peticiones.online/api/userss"`).

